BEGIN;
CREATE TABLE IF NOT EXISTS evidence_crypto_manifests(id UUID PRIMARY KEY,organization_id UUID NOT NULL,case_id UUID NOT NULL,evidence_id UUID NOT NULL,object_uri TEXT NOT NULL,object_version_id TEXT NOT NULL,evidence_sha256 CHAR(64) NOT NULL,previous_manifest_sha256 CHAR(64),encryption_key_id TEXT NOT NULL,signing_key_id TEXT NOT NULL,manifest_sha256 CHAR(64) NOT NULL,signature TEXT NOT NULL,collected_by UUID NOT NULL,collected_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,evidence_id),UNIQUE(organization_id,manifest_sha256));
CREATE TABLE IF NOT EXISTS evidence_integrity_verifications(id UUID PRIMARY KEY,organization_id UUID NOT NULL,evidence_id UUID NOT NULL,manifest_sha256 CHAR(64) NOT NULL,object_hash_verified BOOLEAN NOT NULL,signature_verified BOOLEAN NOT NULL,chain_verified BOOLEAN NOT NULL,verified_by UUID,verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),details JSONB NOT NULL DEFAULT '{}');
ALTER TABLE evidence_custody_events ADD COLUMN IF NOT EXISTS previous_event_hash CHAR(64);
ALTER TABLE evidence_custody_events ADD COLUMN IF NOT EXISTS event_hash CHAR(64);
CREATE TABLE IF NOT EXISTS evidence_worm_attestations(id UUID PRIMARY KEY,organization_id UUID NOT NULL,evidence_id UUID NOT NULL,provider TEXT NOT NULL,bucket TEXT NOT NULL,object_version_id TEXT NOT NULL,retention_mode TEXT NOT NULL,retain_until TIMESTAMPTZ NOT NULL,legal_hold BOOLEAN NOT NULL,provider_request_id TEXT NOT NULL,attested_by UUID,attested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,evidence_id));
CREATE TABLE IF NOT EXISTS evidence_destruction_certificates(id UUID PRIMARY KEY,organization_id UUID NOT NULL,evidence_id UUID NOT NULL,certificate_sha256 CHAR(64) NOT NULL,certificate JSONB NOT NULL,signing_key_id TEXT NOT NULL,signature TEXT NOT NULL,approved_by UUID NOT NULL,destroyed_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,evidence_id));
COMMIT;
